      "sha256": "a0a22af3fba7d04310c6332afab61f74298c6f363bfe0d6215299c46f9602f92",
      "lines": 1495
    }
  ],
  "audit": {
    "named_axiom_probes": 12,
    "callers": 16
  },
  "findings": [
    {
      "topic": "Correct substitution vector",
      "finding": "qVecIter d of the singleton free variable retains lower slots i<d and replaces slot d by the same free index. Its type is (d+1) source slots into depth d. Instantiation keeps F unchanged, in contrast to Opening, which first shifts source free variables."
    },
    {
      "topic": "Term interpretation",
      "finding": "Ext d B Bprime (freeLabel F index) gives the exact lower-coordinate and final-coordinate equalities needed for bound terms. Already free terms remain unchanged; function terms are excluded by the actual empty function language. The vector equality checks typed lengths and each coordinate."
    },
    {
      "topic": "Binder step",
      "finding": "Both sides push the same allocated label, advance fresh by2, and use ext_cons with d+1. qVec lifting preserves the selected free index. No external-natural iteration or bound replaces the internal d/index/source quantifiers."
    },
    {
      "topic": "Hierarchy",
      "finding": "The universal invariant concludes equality of total Delta1 functions under an Ext Delta1 antecedent, so Pi1 induction in I-Sigma1 is appropriate. Fixed qVecIter/subst/len graph instances and the maintained freeLabel/encode Delta1 instances supply the intended compositional definability."
    },
    {
      "topic": "EXS term coverage",
      "finding": "At depth0, every internally typed term in the set language is a free variable: bound-variable case is impossible and the function relation is false. Thus encode_substs1 covers the actual arbitrary typed source term, including the fallback label1 when its free index is outside F."
    },
    {
      "topic": "No freshness implied",
      "finding": "These are literal encoder equalities and require no positivity, injectivity, or stream-freshness premise. Equalities remain valid if an interpreted free label collides with a binder label; any later CProv existential-introduction step must supply its own valid logical resources. The file does not establish that CProv rule or a proof compiler."
    },
    {
      "topic": "Audit",
      "finding": "Focused clients exercise lifted vectors, terms/atoms, ALL/EXS, generalized and depth-zero identities, arbitrary typed terms, empty-F fallback, Bottom, and the relation to the existing opening identity. Elaboration and reported axioms await root execution."
    }
  ],
  "blocking_mathematical_findings": [],
  "suggested_immediate_changes": [],
  "proof_replays": 0
}

